//variables : F  X
//constants : +  -  [  ]
//axiom     : X
//rules     : X → F+[[X]-X]-F[-FX]+X
//           F → FF
//angle     : 25°



#define F      0   // “draw forward”
#define X      1   // produces branches
#define PLUS   2   // turn +θ
#define MINUS  3   // turn –θ
#define PUSH   4   // [
#define POP    5   // ]

// --- rule lengths  ---
#define RLEN_F   2                    // F  → FF
#define RLEN_X   13                   // X  → F+[[X]-X]-F[-FX]+X
#define MAX_LEN  1600                 
#define ITER     5                    // how many rewrites
#define ANGDEG   25.0                 // θ

int curr[MAX_LEN];
int next[MAX_LEN];
int string_len;



const float STEP   = 0.05;              // forward step length (scene scale)
const float THICK  = 0.007;             // visual branch thickness in NDC
const vec3  BRANCH = vec3(1.0);         
const vec3  BACK   = vec3(0.0);         


void grow(){

    int len = 1;
    curr[0] = X;  // Axiom

    for (int cycle = 0; cycle < ITER; ++cycle){
        int n = 0;
        for (int i = 0; i < len; ++i){  // How many rules can be read at once

            int s = curr[i];
            if (s == F) {
            // F -> FF
            next[n++] = F;
            next[n++] = F;

            }
            else if (s == X){   // X → F+[[X]-X]-F[-FX]+X  
                next[n++] = F; next[n++] = PLUS; 
                next[n++] = PUSH;
                    next[n++] = PUSH;
                        next[n++] = X;
                    next[n++] = POP;
                    next[n++] = MINUS;
                    next[n++] = X;
                next[n++] = POP;
                next[n++] = MINUS; next[n++] = F;
                next[n++] = PUSH;
                    next[n++] = MINUS;
                    next[n++] = F;
                    next[n++] = X;
                next[n++] = POP;
                next[n++] = PLUS; next[n++] = X;
            }
            else
            {   
                next[n++] = s;
            }

        }
        for (int k = 0; k < n; ++k) curr[k] = next[k];
        len = n;



    }
    string_len = len;



}

// ===== SDF =========


float sdSegment(vec2 p, vec2 a, vec2 b)
{
    vec2 pa = p - a;
    vec2 ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}

void forward(inout vec2 pos,
             float heading,
             vec2  uv,
             inout float minD,
             float step)
{
    vec2 newPos = pos + step * vec2(cos(heading), sin(heading));
    minD = min(minD, sdSegment(uv, pos, newPos));   // distance update
    pos  = newPos;                                  
}


void turn(inout float heading, float delta)
{
    heading += delta * sin(iTime * 0.1);
}


#define STACK_MAX 64      // must match your earlier constant

void pushState(vec2  pos,
               float heading,
               inout vec2  pStack[STACK_MAX],
               inout float aStack[STACK_MAX],
               inout int   sp)
{
    pStack[sp] = pos;
    aStack[sp] = heading;
    ++sp;
}

void popState(out vec2  pos,
              out float heading,
              inout vec2  pStack[STACK_MAX],
              inout float aStack[STACK_MAX],
              inout int   sp)
{
    --sp;
    pos     = pStack[sp];
    heading = aStack[sp];
}




vec3 turtleWalk(vec2 uv)
{
    /* ── initial turtle state ── */
    vec2  pos = vec2(-1.0);              // start at scene origin
    float ang = radians(30.0);          // pointing straight up

    vec2  pStack[STACK_MAX];
    float aStack[STACK_MAX];
    int   sp = 0;                       // stack pointer

    float minD = 1e5;                   // “no branch seen yet”

    /* ── walk through every symbol ── */
    for (int i = 0; i < string_len; ++i)

    {
        int sym = curr[i];

        if (sym == F)                            // draw forward
        {
            forward(pos, ang, uv, minD, STEP);
        }
        else if (sym == PLUS)                    // rotate +
        {
            ang += radians(ANGDEG * sin(iTime * 0.01));
        }
        else if (sym == MINUS)                   // rotate –
        {
            ang -= radians(ANGDEG * cos(iTime * 0.01));
        }
        else if (sym == PUSH)                    // save state
        {
            pStack[sp] = pos;
            aStack[sp] = ang;
            ++sp;
        }
        else if (sym == POP)                     // restore state
        {
            --sp;
            pos = pStack[sp];
            ang = aStack[sp];
        }
    }

    /* ── convert distance → colour ── */
    float edge = smoothstep(THICK, THICK * 0.5, minD);
    return mix(BRANCH, BACK, edge);              // branch where edge≈0
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / iResolution.y;

    // Time varying pixel color
    grow();
    vec3 col = turtleWalk(uv);

    // Output to screen
    fragColor = vec4(col,1.0);
}
